package ds.seed6733;

import ds.Grafo;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;
import org.junit.experimental.categories.Category;

import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;

/**
 * Unit test suite for ds.Grafo (improved from autogenerated tests).
 *
 * Traceability:
 *  - Tests reference requirement IDs: REQ-001 .. REQ-008
 *
 * Notes:
 *  - Tests follow a Given-When-Then structure in comments.
 *  - Each test includes descriptive assertion messages.
 */
interface UnitTest {}

@RunWith(JUnit4.class)
@Category(UnitTest.class)
public class EvoAITest extends Grafo_ESTest_scaffolding {

  /**
   * REQ-001
   * Given a graph with N vertices,
   * When an edge is inserted and the graph is printed,
   * Then the number of vertices must remain unchanged and the inserted edge should exist.
   */
  @Test(timeout = 4000)
  public void test0()  throws Throwable  {
    // Given
    final int V = 1003;
    Grafo grafo0 = new Grafo(V);

    // When
    grafo0.insereAresta(937, 0, 937);
    // printing should not change the graph state
    grafo0.imprime();

    // Then
    assertEquals("Vertex count should remain unchanged after inserting an edge and printing", V, grafo0.numVertices());
    assertTrue("Inserted edge (937->0) should exist after insertion",
        grafo0.existeAresta(937, 0));
  }

  /**
   * REQ-002
   * Given a graph and an inserted edge,
   * When the edge is removed,
   * Then the returned Aresta object must reflect the removed edge and the edge should no longer exist.
   */
  @Test(timeout = 4000)
  public void test1()  throws Throwable  {
    // Given
    final int V = 1003;
    Grafo grafo0 = new Grafo(V);
    grafo0.insereAresta(983, 1, 983);

    // When
    Grafo.Aresta removed = grafo0.retiraAresta(983, 1);

    // Then
    assertNotNull("retiraAresta should return a non-null Aresta for an existing edge", removed);
    assertEquals("Removed edge's source (v1) should match", 983, removed.v1());
    assertEquals("Removed edge's target (v2) should match", 1, removed.v2());
    assertEquals("Removed edge's weight (peso) should match", 983, removed.peso());
    assertEquals("Number of vertices should be unchanged after removing an edge", V, grafo0.numVertices());
    assertFalse("Edge (983->1) should no longer exist after removal", grafo0.existeAresta(983, 1));
  }

  /**
   * REQ-003
   * Given a graph with a single directed edge,
   * When the graph is transposed,
   * Then the transposed graph should contain the reversed edge and unrelated removals should return null.
   */
  @Test(timeout = 4000)
  public void test2()  throws Throwable  {
    // Given
    final int V = 1003;
    Grafo grafo0 = new Grafo(V);
    grafo0.insereAresta(937, 0, 937);

    // When
    Grafo grafo1 = grafo0.grafoTransposto();

    // Then
    // after transpose, original 937->0 becomes 0->937
    assertTrue("After transpose, edge (0->937) should exist in the transposed graph", grafo1.existeAresta(0, 937));
    // attempt to remove a non-existing edge should return null (safe call)
    Grafo.Aresta missing = grafo1.retiraAresta(0, 2325);
    assertNull("retiraAresta should return null when removing a non-existent or out-of-range edge", missing);
    assertEquals("Transposed graph should keep the same number of vertices", V, grafo1.numVertices());
  }

  /**
   * REQ-004
   * Given a transposed graph with an invalid insertion (out-of-range vertex index),
   * When attempting to transpose again,
   * Then an ArrayIndexOutOfBoundsException is expected (invalid internal state).
   */
  @Test(timeout = 4000)
  public void test3()  throws Throwable  {
    // Given
    final int V = 1003;
    Grafo grafo0 = new Grafo(V);
    grafo0.insereAresta(968, 0, 968);
    Grafo grafo1 = grafo0.grafoTransposto();

    // Introduce an invalid edge: target index equals V (out-of-range)
    grafo1.insereAresta(0, V, 968);

    // When / Then: expect an ArrayIndexOutOfBoundsException when attempting to transpose back
    try {
      grafo1.grafoTransposto();
      fail("Expected ArrayIndexOutOfBoundsException due to out-of-range vertex index introduced in the graph");
    } catch (ArrayIndexOutOfBoundsException e) {
      // basic checks on the exception to ensure it's caused by the invalid index
      String msg = e.getMessage();
      // message may be null in some JVMs; ensure exception was thrown
      assertTrue("ArrayIndexOutOfBoundsException should be thrown for index equal to V (" + V + ")", msg == null || msg.contains(String.valueOf(V)));
    }
  }

  /**
   * REQ-005
   * Given an empty graph,
   * When querying the first adjacency and checking for a self-loop,
   * Then the number of vertices should remain correct and no self-loop should exist.
   */
  @Test(timeout = 4000)
  public void test4()  throws Throwable  {
    // Given
    final int V = 1003;
    Grafo grafo0 = new Grafo(V);

    // When: query first adjacency of vertex 0 (should be a safe no-op on empty adjacency)
    grafo0.primeiroListaAdj(0);

    // Then
    assertEquals("Graph should have the expected number of vertices after querying adjacency", V, grafo0.numVertices());
    // No self-loop by default
    assertFalse("No self-loop (0->0) should exist in a newly created graph", grafo0.existeAresta(0, 0));
  }

  /**
   * REQ-006
   * Given a graph with one inserted edge,
   * When the graph is transposed,
   * Then the edge should be present in the transposed graph in reversed direction and vertex counts preserved.
   */
  @Test(timeout = 4000)
  public void test5()  throws Throwable  {
    // Given
    final int V = 1003;
    Grafo grafo0 = new Grafo(V);
    grafo0.insereAresta(937, 0, 937);

    // When
    Grafo grafo1 = grafo0.grafoTransposto();

    // Then
    assertEquals("Original graph vertex count should remain unchanged", V, grafo0.numVertices());
    assertEquals("Transposed graph vertex count should equal original", V, grafo1.numVertices());
    assertTrue("Original edge (937->0) should exist in the original graph", grafo0.existeAresta(937, 0));
    assertTrue("After transpose, the reversed edge (0->937) should exist", grafo1.existeAresta(0, 937));
  }

  /**
   * REQ-007
   * Given a graph constructed with a particular vertex count,
   * When querying the number of vertices,
   * Then it should report the provided size and not contain any implicit edges.
   */
  @Test(timeout = 4000)
  public void test6()  throws Throwable  {
    // Given
    final int V = 1597;
    Grafo grafo0 = new Grafo(V);

    // When
    int count = grafo0.numVertices();

    // Then
    assertEquals("Graph should report the number of vertices provided at construction", V, count);
    assertFalse("Newly constructed graph should not contain an implicit self-loop at vertex 0", grafo0.existeAresta(0, 0));
  }

  /**
   * REQ-008
   * Given a graph with one edge inserted and then transposed,
   * When checking for an edge that was not inserted,
   * Then existence queries should return false while transposed edge should return true.
   */
  @Test(timeout = 4000)
  public void test7()  throws Throwable  {
    // Given
    final int V = 1003;
    Grafo grafo0 = new Grafo(V);
    grafo0.insereAresta(968, 0, 968);

    // When
    Grafo grafo1 = grafo0.grafoTransposto();

    // Then
    // The transposed graph should contain 0->968
    assertTrue("Transposed graph should contain edge (0->968) after inserting (968->0) in original", grafo1.existeAresta(0, 968));
    // Query for a clearly out-of-range target should be false (and should not throw)
    assertFalse("Querying existence for (0->1003) should return false for valid graphs", grafo1.existeAresta(0, 1003));
    assertEquals("Transposed graph should keep the same number of vertices", V, grafo1.numVertices());
  }
}